<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/customer.php';require_customer();
$a=current_customer();$q=db()->prepare('SELECT p.id,p.code,p.status,p.product_type,p.activated_at,p.project_id,pr.name project_name,(SELECT COUNT(*) FROM scans s WHERE s.plaque_id=p.id) scans FROM plaques p LEFT JOIN projects pr ON pr.id=p.project_id WHERE p.company_id=? ORDER BY p.id DESC');$q->execute([$a['company_id']]);$rows=$q->fetchAll();
layout_start('Minhas placas');
?><div class="heading"><div><span class="eyebrow">PORTAL DA EMPRESA</span><h1>Olá, <?=e($a['name'])?></h1><p><?=e($a['company_name'])?> · Gerencie suas placas e destinos.</p></div><a class="button" href="activate-plaque.php">＋ Ativar placa</a></div><div class="stats"><div class="stat"><small>Placas vinculadas</small><strong><?=count($rows)?></strong></div><div class="stat"><small>Leituras registradas</small><strong><?=array_sum(array_column($rows,'scans'))?></strong></div></div><section class="panel"><div class="section-head"><div><h2>Minhas placas</h2><p>O QR Code e o NFC continuam iguais quando você altera o destino.</p></div></div><div class="tablewrap"><table><thead><tr><th>Placa</th><th>Produto</th><th>Projeto</th><th>Leituras</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><?=e(['google_review'=>'Google','whatsapp'=>'WhatsApp','instagram'=>'Instagram'][$r['product_type']]??'Google')?></td><td><?=e($r['project_name']??'—')?></td><td><?=$r['scans']?></td><td><?=e($r['status'])?></td><td><a href="customer-plaque.php?id=<?=$r['id']?>">Configurar</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Você ainda não possui placas ativadas.</td></tr><?php endif;?></tbody></table></div></section><p><a href="customer-logout.php">Sair da conta</a></p><?php layout_end(); ?>